'use strict';

const { runCompilerPass, fetchCdsEnv } = require('./utils/detection');

class Detector {
  warnings = [];

  async run(rules) {
    const compilerMessages = await runCompilerPass(this.warnings);
    const cdsEnvOutput = await fetchCdsEnv(this.warnings);
    const patternRules = rules.filter(r => !r.compilerPattern);
    const compilerRules = rules.filter(r => r.compilerPattern);
    return {
      compilerMessages,
      cdsEnvOutput,
      patternRules,
      compilerRules,
    };
  }
}

module.exports = Detector;
